import sys
import re
import os

def parse_state_file(path):
    variables = {}
    if os.path.exists(path):
        try:
            with open(path, 'r') as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    match = re.fullmatch(r'^[a-zA-Z][a-zA-Z0-9]*=[-]?\d+$', line)
                    if match:
                        name, value_str = line.split('=', 1)
                        variables[name] = int(value_str)
                    else:
                        print("error: bad state file", file=sys.stderr)
                        sys.exit(1)
        except IOError:
            print("error: bad state file", file=sys.stderr)
            sys.exit(1)
    return variables

def evaluate_expression(expr, variables):
    def parse_token(token):
        if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):
            return int(token)
        if token in variables:
            return variables[token]
        raise ValueError(f"Unknown token: {token}")

    tokens = re.findall(r'[-+*()a-zA-Z0-9]+', expr)
    stack = []
    for token in tokens:
        if token == '(':
            stack.append(token)
        elif token == ')':
            if not stack or stack[-1] != '(':
                raise ValueError("Mismatched parentheses")
            sub_expr = []
            while stack[-1] != '(':
                sub_expr.append(stack.pop())
            stack.pop()  # Remove '('
            sub_expr.reverse()
            try:
                value = evaluate_expression(''.join(sub_expr), variables)
            except ValueError as e:
                raise ValueError(f"Error in sub-expression: {e}")
            stack.append(str(value))
        else:
            try:
                value = parse_token(token)
            except ValueError as e:
                raise ValueError(f"Error parsing token: {e}")
            stack.append(str(value))

    if len(stack) != 1:
        raise ValueError("Invalid expression")

    try:
        return int(''.join(stack[0]))
    except ValueError:
        raise ValueError("Invalid expression")

def main():
    if len(sys.argv) != 2:
        print("Usage: python calc.py <state_file>", file=sys.stderr)
        sys.exit(1)

    state_file = sys.argv[1]
    variables = parse_state_file(state_file)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        if '=' in line:
            name, expr = line.split('=', 1)
            name = name.strip()
            expr = expr.strip()
            try:
                value = evaluate_expression(expr, variables)
                variables[name] = value
            except ValueError as e:
                print(f"error: {e}", file=sys.stderr)
                sys.exit(1)
        else:
            try:
                name = line.strip()
                if name not in variables:
                    print(f"error: undefined name", file=sys.stderr)
                    sys.exit(1)
                print(variables[name])
            except ValueError:
                print(f"error: undefined name", file=sys.stderr)
                sys.exit(1)

    with open(state_file, 'w') as f:
        for name in sorted(variables.keys()):
            f.write(f"{name}={variables[name]}\n")

