import sys
import re
import os

def parse_state_file(state_file):
    variables = {}
    try:
        with open(state_file, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                match = re.match(r'([a-zA-Z][a-zA-Z0-9]*)=(-?\d+)', line)
                if not match:
                    print("error: bad state file", file=sys.stderr)
                    sys.exit(1)
                name, value = match.groups()
                variables[name] = int(value)
    except FileNotFoundError:
        pass
    return variables

def evaluate_expression(expr, variables):
    # Replace variables with their values
    for name in list(variables.keys()):
        expr = expr.replace(name, str(variables[name]))

    # Tokenize the expression
    tokens = re.findall(r'\(|\)|\d+|[-+*]|[a-zA-Z][a-zA-Z0-9]*', expr)

    # Convert tokens to postfix notation (Reverse Polish Notation)
    output = []
    operators = []
    precedence = {'+': 1, '-': 1, '*': 2}

    for token in tokens:
        if token.isdigit():
            output.append(token)
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                output.append(operators.pop())
            if not operators:
                print("error: bad state file", file=sys.stderr)
                sys.exit(1)
            operators.pop()  # Remove the '('
        else:  # Operator
            while (operators and operators[-1] != '(' and
                   precedence[operators[-1]] >= precedence[token]):
                output.append(operators.pop())
            operators.append(token)

    while operators:
        if operators[-1] == '(':
            print("error: bad state file", file=sys.stderr)
            sys.exit(1)
        output.append(operators.pop())

    # Evaluate postfix expression
    stack = []
    for token in output:
        if token.isdigit():
            stack.append(int(token))
        else:
            if len(stack) < 2:
                print("error: undefined name", file=sys.stderr)
                sys.exit(1)
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)

    if len(stack) != 1:
        print("error: undefined name", file=sys.stderr)
        sys.exit(1)
    return stack[0]

def main():
    if len(sys.argv) != 2:
        print("Usage: python calc.py <state_file>", file=sys.stderr)
        sys.exit(1)

    state_file = sys.argv[1]
    variables = parse_state_file(state_file)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        if '=' in line:
            # Assignment
            name, expr = line.split('=', 1)
            name = name.strip()
            expr = expr.strip()
            if not re.match(r'^[a-zA-Z][a-zA-Z0-9]*$', name):
                print("error: bad state file", file=sys.stderr)
                sys.exit(1)
            try:
                value = evaluate_expression(expr, variables)
            except:
                print("error: undefined name", file=sys.stderr)
                sys.exit(1)
            variables[name] = value
        elif line.startswith('print '):
            # Print command
            name = line[6:].strip()
            if not re.match(r'^[a-zA-Z][a-zA-Z0-9]*$', name):
                print("error: bad state file", file=sys.stderr)
                sys.exit(1)
            if name not in variables:
                print("error: undefined name", file=sys.stderr)
                sys.exit(1)
            print(variables[name])
        else:
            print("error: invalid command", file=sys.stderr)
            sys.exit(1)

    # Save variables to state file
    with open(state_file, 'w') as f:
        for name in sorted(variables.keys()):
            f.write(f"{name}={variables[name]}\n")

if __name__ == "__main__":
    main()

import sys
import re
import operator

def parse_state_file(path):
    vars_table = {}
    try:
        with open(path, 'r') as f:
            for line in f:
                stripped = line.strip()
                if not stripped:
                    continue
                parts = stripped.split('=', 1)
                if len(parts) != 2:
                    print("error: bad state file", file=sys.stderr)
                    sys.exit(1)
                name, value_str = parts
                if not re.fullmatch(r'^[a-zA-Z][a-zA-Z0-9]*$', name):
                    print("error: bad state file", file=sys.stderr)
                    sys.exit(1)
                if not value_str.lstrip('-').isdigit():
                    print("error: bad state file", file=sys.stderr)
                    sys.exit(1)
                vars_table[name] = int(value_str)
    except FileNotFoundError:
        pass
    return vars_table

def evaluate_expression(expr, vars_table):
    tokens = re.findall(r'[-+*()a-zA-Z0-9]+', expr)
    stack = []
    ops = []
    for token in tokens:
        if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):
            stack.append(int(token))
        elif token in vars_table:
            stack.append(vars_table[token])
        elif token == '(':
            ops.append(token)
        elif token == ')':
            while ops and ops[-1] != '(':
                a = stack.pop()
                b = stack.pop()
                op = ops.pop()
                if op == '+':
                    stack.append(a + b)
                elif op == '-':
                    stack.append(a - b)
                elif op == '*':
                    stack.append(a * b)
            ops.pop()  # Remove '('
        elif token in '+-*' and ops and ops[-1] not in '()':
            while ops and ops[-1] != '(' and (
                (token in '+-' and ops[-1] in '+-*') or
                (token == '*' and ops[-1] in '+-*')
            ):
                a = stack.pop()
                b = stack.pop()
                op = ops.pop()
                if op == '+':
                    stack.append(a + b)
                elif op == '-':
                    stack.append(a - b)
                elif op == '*':
                    stack.append(a * b)
            ops.append(token)
    while ops:
        a = stack.pop()
        b = stack.pop()
        op = ops.pop()
        if op == '+':
            stack.append(a + b)
        elif op == '-':
            stack.append(a - b)
        elif op == '*':
            stack.append(a * b)
    return stack[0] if stack else 0

def main():
    if len(sys.argv) != 2:
        print("Usage: python calc.py <state_file>", file=sys.stderr)
        sys.exit(1)

    state_file = sys.argv[1]
    vars_table = parse_state_file(state_file)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        if '=' in line:
            parts = line.split('=', 1)
            name = parts[0].strip()
            expr = parts[1].strip()
            if not re.fullmatch(r'^[a-zA-Z][a-zA-Z0-9]*$', name):
                print("error: undefined name", file=sys.stderr)
                sys.exit(1)
            try:
                value = evaluate_expression(expr, vars_table)
            except:
                print("error: undefined name", file=sys.stderr)
                sys.exit(1)
            vars_table[name] = value
